package com.eonmux.neuralfree.gguf.tokenizer;

/**
 * Code-point classification used by the pre-tokenizer splitters, mirroring llama.cpp
 * {@code unicode_cpt_flags} (src/unicode.h) as generated by scripts/gen-unicode-data.py: one
 * general-category bit per code point plus the whitespace bit.
 *
 * <p>Categories come from the JDK's Unicode tables ({@link Character#getType(int)}) with the same
 * category-to-flag mapping as the llama.cpp generator; whitespace is
 * {@link TokenizerVocab#isWhitespace(int)}, the llama.cpp {@code unicode_set_whitespace}.</p>
 */
final class UnicodeFlags {

    /** {@code Cn}: unassigned. */
    static final int UNDEFINED = 0x0001;
    /** {@code \p{N}}. */
    static final int NUMBER = 0x0002;
    /** {@code \p{L}}. */
    static final int LETTER = 0x0004;
    /** {@code \p{Z}}. */
    static final int SEPARATOR = 0x0008;
    /** {@code \p{M}}. */
    static final int ACCENT_MARK = 0x0010;
    /** {@code \p{P}}. */
    static final int PUNCTUATION = 0x0020;
    /** {@code \p{S}}. */
    static final int SYMBOL = 0x0040;
    /** {@code \p{C}} without {@code Cn}: control, format, private use and surrogate. */
    static final int CONTROL = 0x0080;
    /** The general-category bits. */
    static final int MASK_CATEGORIES = 0x00FF;
    /** {@code \s} in llama.cpp's sense. */
    static final int WHITESPACE = 0x0100;

    private UnicodeFlags() {}

    /** The flags of one code point; never 0 for a valid code point. */
    static int of(int cp) {
        int flags = category(cp);
        if (TokenizerVocab.isWhitespace(cp)) flags |= WHITESPACE;
        return flags;
    }

    /** Flags for each code point of an array. */
    static int[] of(int[] cps) {
        int[] flags = new int[cps.length];
        for (int i = 0; i < cps.length; i++) flags[i] = of(cps[i]);
        return flags;
    }

    private static int category(int cp) {
        if (cp < 0 || cp > Character.MAX_CODE_POINT) return UNDEFINED;
        switch (Character.getType(cp)) {
            case Character.UPPERCASE_LETTER:
            case Character.LOWERCASE_LETTER:
            case Character.TITLECASE_LETTER:
            case Character.MODIFIER_LETTER:
            case Character.OTHER_LETTER:
                return LETTER;
            case Character.NON_SPACING_MARK:
            case Character.ENCLOSING_MARK:
            case Character.COMBINING_SPACING_MARK:
                return ACCENT_MARK;
            case Character.DECIMAL_DIGIT_NUMBER:
            case Character.LETTER_NUMBER:
            case Character.OTHER_NUMBER:
                return NUMBER;
            case Character.SPACE_SEPARATOR:
            case Character.LINE_SEPARATOR:
            case Character.PARAGRAPH_SEPARATOR:
                return SEPARATOR;
            case Character.CONTROL:
            case Character.FORMAT:
            case Character.PRIVATE_USE:
            case Character.SURROGATE:
                return CONTROL;
            case Character.DASH_PUNCTUATION:
            case Character.START_PUNCTUATION:
            case Character.END_PUNCTUATION:
            case Character.CONNECTOR_PUNCTUATION:
            case Character.OTHER_PUNCTUATION:
            case Character.INITIAL_QUOTE_PUNCTUATION:
            case Character.FINAL_QUOTE_PUNCTUATION:
                return PUNCTUATION;
            case Character.MATH_SYMBOL:
            case Character.CURRENCY_SYMBOL:
            case Character.MODIFIER_SYMBOL:
            case Character.OTHER_SYMBOL:
                return SYMBOL;
            default:
                return UNDEFINED;
        }
    }

    /** {@code unicode_tolower}: the simple lowercase mapping; other values map to themselves. */
    static int toLower(int cp) {
        return cp < 0 || cp > Character.MAX_CODE_POINT ? cp : Character.toLowerCase(cp);
    }

    /** {@code unicode_cpt_is_han} (src/unicode.cpp:1452-1482). */
    static boolean isHan(int cp) {
        return (cp >= 0x4E00 && cp <= 0x9FFF)
                || (cp >= 0x3400 && cp <= 0x4DBF)
                || (cp >= 0x20000 && cp <= 0x2A6DF)
                || (cp >= 0x2A700 && cp <= 0x2B73F)
                || (cp >= 0x2B740 && cp <= 0x2B81F)
                || (cp >= 0x2B820 && cp <= 0x2CEAF)
                || (cp >= 0x2CEB0 && cp <= 0x2EBEF)
                || (cp >= 0xF900 && cp <= 0xFAFF)
                || (cp >= 0x2F800 && cp <= 0x2FA1F);
    }
}
